class Solution {
    public int rangeBitwiseAnd(int left,int right){
        int shift=0;
        while(left!=right){
            left>>=1;
            right>>=1;
            shift++;
        }
        return left<<shift;
    }
}

code.kotlin:
class Solution {
    fun rangeBitwiseAnd(leftValue:Int,rightValue:Int):Int{
        var left=leftValue;
        var right=rightValue;
        var shift=0;
        while(left!=right){
            left=left shr 1;
            right=right shr 1;
            shift++
        };
        return left shl shift
    }
}

